const jobs = new Map(); // job_id -> 'running' | 'cancelled'

export async function listTools() {
  return [
    {
      name: 'start_job',
      description: 'Start a job with the given job_id. Returns running status. Rejects duplicate active jobs.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'Unique identifier for the job' }
        },
        required: ['job_id']
      }
    },
    {
      name: 'cancel_job',
      description: 'Cancel an active job by job_id. Rejects missing jobs or repeated cancellation.',
      inputSchema: {
        type: 'object',
        properties: {
          job_id: { type: 'string', description: 'Unique identifier for the job' }
        },
        required: ['job_id']
      }
    }
  ];
}

function validateJobId(args) {
  if (args == null || typeof args.job_id !== 'string' || args.job_id.length === 0) {
    throw new Error('job_id is required');
  }
}

export async function callTool(name, args = {}) {
  validateJobId(args);
  const job_id = args.job_id;
  if (name === 'start_job') {
    if (jobs.get(job_id) === 'running') {
      throw new Error('job already active: ' + job_id);
    }
    jobs.set(job_id, 'running');
    return { content: [{ type: 'text', text: 'job ' + job_id + ' running' }] };
  }
  if (name === 'cancel_job') {
    const status = jobs.get(job_id);
    if (status === undefined) {
      throw new Error('job not found: ' + job_id);
    }
    if (status === 'cancelled') {
      throw new Error('job already cancelled: ' + job_id);
    }
    jobs.set(job_id, 'cancelled');
    return { content: [{ type: 'text', text: 'job ' + job_id + ' cancelled' }] };
  }
  throw new Error('unknown tool: ' + name);
}
```

